package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Differential regression coverage for filter-expression semantics: every query must return the same rows with the
 * native LMDB engine enabled and disabled. Each test targets a seam where the native expression path historically
 * diverged from the generic evaluator (REGEX flag handling, string-relation argument compatibility, and order
 * comparisons over operands the fast native comparison cannot decide).
 */
public class LmdbNativeExpressionSemanticsDivergenceTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI label = vf.createIRI(EX, "label");
			IRI name = vf.createIRI(EX, "name");
			IRI name2 = vf.createIRI(EX, "name2");
			IRI date = vf.createIRI(EX, "date");
			IRI flag = vf.createIRI(EX, "flag");
			IRI ref = vf.createIRI(EX, "ref");

			conn.add(vf.createIRI(EX, "s1"), label, vf.createLiteral("abc", "en"));
			conn.add(vf.createIRI(EX, "s2"), label, vf.createLiteral("abc", "fr"));
			conn.add(vf.createIRI(EX, "s3"), label, vf.createLiteral("abc"));
			conn.add(vf.createIRI(EX, "s4"), label, vf.createLiteral("a.c"));

			conn.add(vf.createIRI(EX, "s1"), name, vf.createLiteral("apple", "en"));
			conn.add(vf.createIRI(EX, "s1"), name2, vf.createLiteral("banana", "en"));
			conn.add(vf.createIRI(EX, "s2"), name, vf.createLiteral("cherry", "en"));
			conn.add(vf.createIRI(EX, "s2"), name2, vf.createLiteral("apple", "en"));

			conn.add(vf.createIRI(EX, "d1"), date, vf.createLiteral("2024-01-01", XSD.DATE));
			conn.add(vf.createIRI(EX, "d2"), date, vf.createLiteral("2025-01-01", XSD.DATE));

			conn.add(vf.createIRI(EX, "b1"), flag, vf.createLiteral(true));
			conn.add(vf.createIRI(EX, "b2"), flag, vf.createLiteral(false));

			conn.add(vf.createIRI(EX, "r1"), ref, vf.createIRI(EX, "aaa"));
			conn.add(vf.createIRI(EX, "r2"), ref, vf.createIRI(EX, "zzz"));
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private List<BindingSet> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private void assertSameRowCount(String query) {
		int generic = rows(query, false).size();
		assertThat(rows(query, true).size()).as("native row count must match generic for:\n%s", query)
				.isEqualTo(generic);
	}

	@Test
	public void regexLiteralQFlagMatchesGeneric() {
		// "q" = Pattern.LITERAL: only the literal label "a.c" matches; the native path used to drop the flag and
		// treat "a.c" as a regular expression, also matching every "abc" label
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:label ?label . FILTER(REGEX(?label, \"a.c\", \"q\")) }";
		assertThat(rows(query, false)).hasSize(1);
		assertSameRowCount(query);
	}

	@Test
	public void regexUnknownFlagMatchesGeneric() {
		// the generic engine raises a type error for unknown flags (the filter yields no rows); the native path
		// used to silently ignore them and match
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:label ?label . FILTER(REGEX(?label, \"abc\", \"zz\")) }";
		assertThat(rows(query, false)).isEmpty();
		assertSameRowCount(query);
	}

	@Test
	public void strStartsLanguageCompatibilityMatchesGeneric() {
		// STRSTARTS("abc"@en, "a"@fr) is a type error generically; only the @fr label is compatible
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:label ?label . FILTER(STRSTARTS(?label, \"a\"@fr)) }";
		assertThat(rows(query, false)).hasSize(1);
		assertSameRowCount(query);
	}

	@Test
	public void containsLanguageCompatibilityMatchesGeneric() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:label ?label . FILTER(CONTAINS(?label, \"b\"@en)) }";
		assertThat(rows(query, false)).hasSize(1);
		assertSameRowCount(query);
	}

	@Test
	public void strEndsLanguageCompatibilityMatchesGeneric() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:label ?label . FILTER(STRENDS(?label, \"c\"@fr)) }";
		assertThat(rows(query, false)).hasSize(1);
		assertSameRowCount(query);
	}

	@Test
	public void strStartsLanguageAgainstSimpleLiteralMatchesGeneric() {
		// a language literal compared against a simple literal IS compatible (argument-compatibility rule 4):
		// this guards the fix against over-restricting
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:label ?label . FILTER(STRSTARTS(?label, \"ab\")) }";
		assertThat(rows(query, false)).hasSize(3);
		assertSameRowCount(query);
	}

	@Test
	public void lcaseKeepsLanguageTagMatchesGeneric() {
		// LCASE preserves the input's language tag, so LCASE("abc"@en) stays compatible with "b"@en
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:label ?label . FILTER(CONTAINS(LCASE(?label), \"b\"@en)) }";
		assertThat(rows(query, false)).hasSize(1);
		assertSameRowCount(query);
	}

	@Test
	public void sameLanguageOrderComparisonMatchesGeneric() {
		// order comparison over two language-tagged literals is a type error generically; the native path used to
		// order them by label
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:name ?name ; ex:name2 ?name2 . FILTER(COALESCE(?name) < ?name2) }";
		assertThat(rows(query, false)).isEmpty();
		assertSameRowCount(query);
	}

	@Test
	public void dateOrderComparisonBehindAnchorMatchesGeneric() {
		// the generic engine orders xsd:date correctly; the anchored native comparison used to return a hard type
		// error (dropping the matching row) because dates are neither numeric nor plain strings
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n"
				+ "SELECT ?s WHERE { ?s ex:date ?date . FILTER(COALESCE(?date) < \"2024-06-01\"^^xsd:date) }";
		assertThat(rows(query, false)).hasSize(1);
		assertSameRowCount(query);
	}

	@Test
	public void booleanOrderComparisonBehindAnchorMatchesGeneric() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:flag ?flag . FILTER(COALESCE(?flag) > false) }";
		assertThat(rows(query, false)).hasSize(1);
		assertSameRowCount(query);
	}

	@Test
	public void iriOrderComparisonBehindAnchorMatchesGeneric() {
		// order comparisons over IRIs are a type error generically; the native comparison used to order them by
		// their string form
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:ref ?ref . FILTER(COALESCE(?ref) < ex:mmm) }";
		assertThat(rows(query, false)).isEmpty();
		assertSameRowCount(query);
	}
}
